"""Qwen3 ForcedAligner (-hf) word/char timestamps via TokenClassification."""

from __future__ import annotations

import logging
from typing import Any

_log = logging.getLogger("transub_engine.asr.qwen3_hf_align")

# ForcedAligner needs two ``<timestamp>`` slots per word (start + end). The Hub
# chat_template.jinja joins words with ASCII spaces, which BPE encodes as ``Ġ`` /
# id 220 — never as ``timestamp_token_id`` (151705). Offline / legacy packs then
# decode with an empty mask → ``max() iterable argument is empty``. Build the
# text ourselves so every word contributes exactly two timestamp tokens.
_TIMESTAMP = "<timestamp>"
_AUDIO_PLACEHOLDER = "<|audio_start|><|audio_pad|><|audio_end|>"


class _TsItem:
    __slots__ = ("text", "start_time", "end_time", "start", "end", "word")

    def __init__(self, text: str, start: float, end: float) -> None:
        self.text = text
        self.word = text
        self.start_time = float(start)
        self.end_time = float(end)
        self.start = float(start)
        self.end = float(end)


def _normalize_timestamp_rows(rows: Any) -> list[_TsItem]:
    out: list[_TsItem] = []
    if not rows:
        return out
    if isinstance(rows, dict):
        rows = [rows]
    for row in rows:
        if isinstance(row, dict):
            text = str(row.get("text") or row.get("word") or "").strip()
            start = float(row.get("start_time", row.get("start", 0)) or 0)
            end = float(row.get("end_time", row.get("end", start)) or start)
        else:
            text = str(
                getattr(row, "text", None) or getattr(row, "word", None) or ""
            ).strip()
            start = float(
                getattr(row, "start_time", None) or getattr(row, "start", 0) or 0
            )
            end = float(
                getattr(row, "end_time", None) or getattr(row, "end", start) or start
            )
        if not text:
            continue
        out.append(_TsItem(text, start, max(end, start)))
    return out


def _build_aligner_text(word_list: list[str]) -> str:
    """Audio placeholder + per-word text followed by start/end timestamp markers."""
    body = "".join(f"{word}{_TIMESTAMP}{_TIMESTAMP}" for word in word_list if word)
    return f"{_AUDIO_PLACEHOLDER}{body}"


def _normalize_align_audio(audio: Any) -> Any:
    """Pass path / URL / ndarray / (ndarray, sr) through to the processor."""
    return audio


def _pad_aligner_mel_features(aligner_inputs: Any, *, n_window: int = 50) -> Any:
    """Right-pad mel frames to ``2 * n_window`` (Qwen3ASREncoder chunk contract).

    Hybrid ForcedAligner packs may still load WhisperFeatureExtractor, which
    skips this pad and every forward raises ``padded_feature_length … 100``.
    """
    if aligner_inputs is None:
        return aligner_inputs
    try:
        import torch
    except Exception:
        return aligner_inputs

    multiple = max(2, int(n_window or 50) * 2)
    feat = None
    mask = None
    try:
        feat = aligner_inputs.get("input_features")
        mask = aligner_inputs.get("input_features_mask")
        if mask is None:
            mask = aligner_inputs.get("attention_mask")
    except Exception:
        return aligner_inputs
    if feat is None:
        return aligner_inputs

    try:
        length = int(feat.shape[-1])
    except Exception:
        return aligner_inputs
    remainder = length % multiple
    if remainder == 0:
        return aligner_inputs
    pad = multiple - remainder

    try:
        if hasattr(feat, "new_zeros"):
            zeros = feat.new_zeros(*feat.shape[:-1], pad)
            feat = torch.cat([feat, zeros], dim=-1)
        else:
            import numpy as np

            feat = np.pad(feat, [(0, 0)] * (feat.ndim - 1) + [(0, pad)])
        aligner_inputs["input_features"] = feat
        if mask is not None:
            if hasattr(mask, "new_zeros"):
                m_pad = mask.new_zeros(*mask.shape[:-1], pad)
                mask = torch.cat([mask, m_pad], dim=-1)
            else:
                import numpy as np

                mask = np.pad(mask, [(0, 0)] * (mask.ndim - 1) + [(0, pad)])
            if "input_features_mask" in aligner_inputs:
                aligner_inputs["input_features_mask"] = mask
            elif "attention_mask" in aligner_inputs and "input_ids" not in aligner_inputs:
                aligner_inputs["attention_mask"] = mask
            else:
                aligner_inputs["input_features_mask"] = mask
    except Exception as err:
        _log.warning("ForcedAligner mel pad failed: %s", err)
    return aligner_inputs


def _prepare_aligner_batch(
    aligner_processor: Any,
    *,
    audio: Any,
    transcript: str,
    language: str | None,
) -> tuple[Any, list[list[str]]]:
    """Build ForcedAligner inputs with explicit ``<timestamp>`` slots.

    Prefer a patched chat-template path when it already emits timestamp ids;
    otherwise tokenize ``audio_pad + word + <timestamp><timestamp>…`` ourselves
    (same contract as Qwen's original ``encode_timestamp``, but with real
    timestamp tokens instead of spaces).
    """
    lang = language
    word_list = aligner_processor.split_words_for_alignment(transcript, lang)
    if not word_list:
        return None, [[]]

    # Fast path: official jinja that already inserts ``<timestamp>``.
    try:
        aligner_inputs, word_lists = aligner_processor.prepare_forced_aligner_inputs(
            audio=audio,
            transcript=transcript,
            language=lang,
        )
        ts_id = getattr(
            getattr(aligner_processor, "tokenizer", None),
            "convert_tokens_to_ids",
            None,
        )
        timestamp_id = None
        if callable(ts_id):
            timestamp_id = int(ts_id(_TIMESTAMP))
        input_ids = aligner_inputs.get("input_ids") if aligner_inputs is not None else None
        if (
            input_ids is not None
            and timestamp_id is not None
            and int((input_ids == timestamp_id).sum().item()) >= 2 * len(word_lists[0])
        ):
            return aligner_inputs, word_lists
    except Exception:
        pass

    text = _build_aligner_text(word_list)
    audio_arr = audio
    sampling_rate = 16000
    if isinstance(audio, tuple) and len(audio) >= 1:
        audio_arr = audio[0]
        if len(audio) >= 2:
            try:
                sampling_rate = int(audio[1]) or 16000
            except Exception:
                sampling_rate = 16000
    aligner_inputs = aligner_processor(
        text=[text],
        audio=[audio_arr],
        return_tensors="pt",
        padding=True,
        sampling_rate=sampling_rate,
    )
    return aligner_inputs, [word_list]


def align_transcript(
    bundle: Any,
    *,
    audio: Any,
    transcript: str,
    language: str | None,
) -> list[_TsItem]:
    """Run ForcedAligner on one clip; return timestamp items compatible with cue builders."""
    text = str(transcript or "").strip()
    if not text or not bundle or not getattr(bundle, "has_aligner", False):
        return []

    import torch

    aligner_processor = bundle.aligner_processor
    aligner_model = bundle.aligner_model
    lang = language or "English"

    try:
        aligner_inputs, word_lists = _prepare_aligner_batch(
            aligner_processor,
            audio=audio,
            transcript=text,
            language=lang,
        )
    except Exception as err:
        _log.warning("ForcedAligner prepare failed: %s", err)
        return []

    if aligner_inputs is None or not word_lists or not word_lists[0]:
        return []

    n_window = 50
    try:
        fe = getattr(aligner_processor, "feature_extractor", None)
        if fe is not None and getattr(fe, "n_window", None):
            n_window = int(fe.n_window)
        else:
            cfg = getattr(aligner_model, "config", None)
            audio_cfg = getattr(cfg, "audio_config", None) if cfg is not None else None
            n_window = int(
                getattr(audio_cfg, "n_window", None)
                or getattr(cfg, "n_window", None)
                or 50
            )
    except Exception:
        n_window = 50
    aligner_inputs = _pad_aligner_mel_features(aligner_inputs, n_window=n_window)

    try:
        if hasattr(aligner_inputs, "to"):
            aligner_inputs = aligner_inputs.to(aligner_model.device, bundle.dtype)
    except Exception:
        try:
            aligner_inputs = aligner_inputs.to(aligner_model.device)
        except Exception:
            pass

    try:
        with torch.inference_mode():
            outputs = aligner_model(**aligner_inputs)
        ts_token = getattr(getattr(aligner_model, "config", None), "timestamp_token_id", None)
        if ts_token is None:
            try:
                ts_token = aligner_processor.tokenizer.convert_tokens_to_ids(_TIMESTAMP)
            except Exception:
                ts_token = 151705
        input_ids = aligner_inputs["input_ids"]
        n_ts = int((input_ids == int(ts_token)).sum().item())
        need = 2 * sum(len(wl) for wl in word_lists)
        if n_ts < need:
            _log.warning(
                "ForcedAligner decode skipped: only %d timestamp token(s), need %d",
                n_ts,
                need,
            )
            return []
        kwargs: dict[str, Any] = {
            "logits": outputs.logits,
            "input_ids": input_ids,
            "word_lists": word_lists,
            "timestamp_token_id": int(ts_token),
        }
        seg = getattr(aligner_processor, "timestamp_segment_time", None)
        if seg is None:
            seg = getattr(getattr(aligner_model, "config", None), "timestamp_segment_time", None)
        if seg is not None:
            kwargs["timestamp_segment_time"] = float(seg)
        decoded = aligner_processor.decode_forced_alignment(**kwargs)
    except Exception as err:
        _log.warning("ForcedAligner decode failed: %s", err)
        return []

    if isinstance(decoded, list) and decoded and isinstance(decoded[0], list):
        rows = decoded[0]
    else:
        rows = decoded
    return _normalize_timestamp_rows(rows)


def attach_time_stamps(result: Any, stamps: list[_TsItem]) -> Any:
    """Return a result-like object with ``.text`` and ``.time_stamps``."""
    text = ""
    if result is not None:
        text = str(
            getattr(result, "text", None)
            or getattr(result, "transcription", None)
            or (result.get("transcription") if isinstance(result, dict) else "")
            or ""
        ).strip()
    lang = getattr(result, "language", None) if result is not None else None

    class _Aligned:
        def __init__(self) -> None:
            self.text = text
            self.transcription = text
            self.language = lang
            self.time_stamps = stamps

    return _Aligned()
